        result = H_EnemyDieVerify.Verify(verifier, tablePos);
        break;
      case PacketType.G_Leave:
        result = G_LeaveVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_Leave:
        result = H_LeaveVerify.Verify(verifier, tablePos);
        break;
      case PacketType.G_ShelterLevel:
        result = G_ShelterLevelVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_ShelterLevel:
        result = H_ShelterLevelVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_SandbagDestroy:
        result = H_SandbagDestroyVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_LoadScene:
        result = H_LoadSceneVerify.Verify(verifier, tablePos);
        break;
      case PacketType.G_SceneReady:
        result = G_SceneReadyVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_EnemySpeak:
        result = H_EnemySpeakVerify.Verify(verifier, tablePos);
        break;
      case PacketType.H_EnemyShoot:
        result = H_EnemyShootVerify.Verify(verifier, tablePos);
        break;
      default: result = true;
        break;
    }
    return result;
  }
}

